POS={0:'صِفْرٌ',1:'وَاحِدٌ',2:'اثْنَانِ',3:'ثَلَاثَةٌ',4:'أَرْبَعَةٌ',5:'خَمْسَةٌ',6:'سِتَّةٌ'}; GEN={1:'وَاحِدٍ',2:'اثْنَيْنِ',3:'ثَلَاثَةٍ',4:'أَرْبَعَةٍ',5:'خَمْسَةٍ',6:'سِتَّةٍ'}
pw=lambda v: POS[v] if v>=0 else 'سَالِبُ '+GEN[-v]
def key(x,y): return ('m%d'%-x if x<0 else '%d'%x)+'_'+('m%d'%-y if y<0 else '%d'%y)
XF={'refV':lambda p:(-p[0],p[1]),'refH':lambda p:(p[0],-p[1]),'rot90':lambda p:(-p[1],p[0]),'rot180':lambda p:(-p[0],-p[1]),'rot270':lambda p:(p[1],-p[0])}
def pick_cands(p,xf):
    x,y=p; img=XF[xf](p); alt={'refV':[(x,-y),(-x,-y)],'refH':[(-x,y),(-x,-y)],'rot90':[(y,-x),(y,x),(-x,-y)],'rot270':[(-y,x),(y,x),(-x,-y)],'rot180':[(-x,y),(x,-y),(-y,x)]}[xf]
    out=[]
    for c in [img,*alt,(-y,-x),(x+1,y)]:
        if c not in out and c!=tuple(p): out.append(c)
    return out[:3]
for p,xf in [((-3,4),'refV'),((2,-5),'rot90')]: PTS.update(pick_cands(p,xf)); PTS.add(p)
p=(3,2); mid=XF['refV'](p); img=XF['rot90'](mid); back=XF['refV'](XF['rot90'](p)); C=[]
for c in [img,mid,XF['rot90'](p),back,(img[0],-img[1]),(-img[0],img[1])]:
    if c not in C and c!=p: C.append(c)
